/**** gbk to utf8 ****/
int gbk2unicode(const unsigned short *pgbk, unsigned short *punicode)
{
	int i; 

	if(NULL == punicode || NULL == pgbk) {
		printf("err: invalid pgbk or punicode\n");
		return -1;
	}

	if(((*pgbk>> 8) == 0) && (*pgbk& 0xff) < 0x80){	//ascll
		*punicode = *pgbk & 0xff;	
		return 0;
	} else {
		for(i = 0; i < MAX_UNI_INDEX; i++) {
			if(*pgbk == uni_table[i][1]) {
				*punicode = uni_table[i][0];
				return 0;
			}
		}
	}

	printf("err: not found gb2312:0x%x in table.\n", *pgbk);
	return -1;
}

int gbk2utf8(const unsigned char *pgbk, int inlen, unsigned char *putf8, int outlen)
{
	int i, j, ret;
	unsigned short sgbk;
	unsigned short sunicode;
	unsigned char c1, c2;

	if(NULL == pgbk || NULL == putf8) {
		printf("err: invalid parameters\n");
		return -1;
	}	

	if(2*inlen > outlen) {
		printf("err: outlen[%d] must bigger than 2*inlen[%d].\n", outlen, inlen);
		return -1;
	}

	i = j = 0;
	while(i < inlen) {
		if(pgbk[i] > 0x7f) {
			sgbk = (pgbk[i] << 8) | pgbk[i+1];	
			ret = gbk2unicode(&sgbk, &sunicode);
			if(ret != -1) {
				c1 = (sunicode >> 8) & 0xff;
				c2 = sunicode & 0xff;
				putf8[j] = 0xef & ((c1 >> 4)|0xf0); 
				putf8[j+1] = 0xbf & ((c1<<2|c2>>6)|0xc0);
				putf8[j+2] = 0xbf & (c2|0xc0);
				j += 3;
				i += 2;
			} else {	//gbk2unicode failure
				i += 2;	
			}
		} else {
			putf8[j] = pgbk[i];
			i++;
			j++;
		}
	}	

	return 0;
}

/**  utf8 to gbk **/
/* unicode 2 gbk */
static int unicode2gbk(const unsigned short *punicode, unsigned short *pgbk)
{
	int left, right, middle;

	if(NULL == punicode || NULL == pgbk) {
		printf("err: invalid pgbk or punicode\n");
		return -1;
	}

	left = middle = 0;
	right = MAX_UNI_INDEX - 1;

	if(((*punicode >> 8) == 0) && (*punicode & 0xff) < 0x80){	//ascll
		*pgbk = *punicode & 0xff;	
		return 0;
	} else {
		while(left <= right) {
			middle = (left + right)/2;
			if(*punicode == uni_table[middle][0]) {
				*pgbk = uni_table[middle][1];
				return 0;
			} else if(*punicode > uni_table[middle][0])
				left = middle + 1;
			else
				right = middle - 1;
		}
	}

	printf("err: not found unicode:0x%x in table.\n", *punicode);
	return -1;
}


int utf82gbk(unsigned char *in, unsigned char *out, int outlen)
{
	unsigned char *p = NULL;
	unsigned short stmp, sgbk;
	int i, j, valid_len;

	if(NULL == in || NULL == out) {
		printf("err: invalid parameters.\n");
		return -1;
	}
	valid_len = strlen(in);
	if(valid_len > outlen) {
		printf("err: invalid outlen[%d], valid_len[%d].\n", outlen, valid_len);
		return -1;
	}

	p = in;
	i = j = 0;
	while(i < valid_len) {
		if(p[i] < 0x80) {	//ascll
			out[j] = p[i];
			i++;
			j++;
		} else {
			/* utf8 to unicode */
			stmp = 0xffff;
			stmp &= (((p[i] | 0xf0) << 12) | 0x0fff);
			stmp &= (((p[i + 1] | 0xc0) << 6) | 0xf03f);
			stmp &= (p[i + 2] | 0xffc0);

			/* unicode 2 gbk */
			if (!unicode2gbk(&stmp, &sgbk)) {
				out[j] = (sgbk >> 8) & 0xff;
				out[j+1] = sgbk & 0xff;
				j += 2;
			}
			i += 3;
		}	
	}

	return 0;
}

